(()=>{
const E=s=>typeof esc==='function'?esc(s):String(s??'');
const docs=()=>{try{return Array.isArray(documents)?documents:[]}catch{return[]}};
const invoiceByNumber=n=>docs().find(d=>d.document_type==='rechnung'&&String(d.document_number||'')===String(n));
const projectOf=inv=>{let p=inv?.payload||{},pid=p.project_id||'';if(pid)return (window.hpProjects||[]).find(x=>String(x.id)===String(pid));let subj=String(p.subject||'').trim().toLowerCase();return (window.hpProjects||[]).find(x=>[x.name,x.site].some(v=>String(v||'').trim().toLowerCase()===subj))};
const reportsFor=inv=>{let p=inv?.payload||{},pr=projectOf(inv),cid=String(p.customer_id||inv.customer_id||'');return docs().filter(d=>{if(d.document_type!=='bautagesbericht')return false;let q=d.payload||{};if(pr&&String(q.project_id||'')===String(pr.id))return true;if(!pr&&cid&&String(q.customer_id||d.customer_id||'')===cid)return true;return false})};
function openNewReport(inv){let pr=projectOf(inv);window.openBautagesbericht?.();setTimeout(()=>{let p=inv.payload||{};if($('btCustomer')&&p.customer_id)$('btCustomer').value=String(p.customer_id);if($('btProject')&&pr){$('btProject').value=String(pr.id);window.hpSyncBtProject?.()}},60)}
function list(inv,rr){let pr=projectOf(inv);$('modalTitle').textContent='Bautagesberichte anhängen';$('modalBody').innerHTML=`<div class="status">${E(pr?.name||inv.payload?.subject||'Rechnung')} · ${rr.length} Bautagesbericht${rr.length===1?'':'e'} gefunden</div><label class="item" style="display:flex;gap:10px;align-items:center;margin-top:10px"><input id="hpBundleAll" type="checkbox" checked onchange="document.querySelectorAll('.hpBundleReport').forEach(x=>x.checked=this.checked)" style="width:22px;height:22px"><strong>Alle auswählen</strong></label><div class="list" style="margin-top:8px">${rr.map(d=>{let p=d.payload||{},dt=p.date?new Date(p.date+'T12:00:00').toLocaleDateString('de-DE'):'';return `<label class="item" style="display:flex;gap:10px;align-items:flex-start"><input class="hpBundleReport" type="checkbox" value="${E(d.id)}" checked style="width:22px;height:22px;margin-top:3px"><div><strong>${E(d.document_number||'Bautagesbericht')}</strong><div class="tiny">${E(dt)} · ${E(p.site||pr?.name||'')}</div>${p.work?`<div style="margin-top:5px">${E(p.work)}</div>`:''}</div></label>`}).join('')}</div><div class="actions"><button class="btn primary" onclick="hpShareInvoiceBundle('${E(inv.id)}')">📤 Rechnung + Berichte senden</button><button class="btn secondary" onclick="hpNewBundleReport('${E(inv.id)}')">+ Bericht</button></div><div id="hpBundleStatus" class="status"></div>`;$('modal').classList.remove('hidden')}
window.hpNewBundleReport=id=>{let inv=docs().find(x=>String(x.id)===String(id));closeModal?.();if(inv)openNewReport(inv)};
window.hpOpenBundle=function(id){let inv=docs().find(d=>String(d.id)===String(id));if(!inv)return alert('Rechnung konnte nicht geladen werden.');let rr=reportsFor(inv);if(!rr.length){openNewReport(inv);return}list(inv,rr)};
async function loadJsPdf(){if(window.jspdf)return;await new Promise((ok,no)=>{let s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js';s.onload=ok;s.onerror=no;document.head.appendChild(s)})}
async function imageData(path){let r=await sb.storage.from('hp-documents').createSignedUrl(path,900);if(!r.data?.signedUrl)return null;let b=await fetch(r.data.signedUrl).then(x=>x.blob());if(!String(b.type).startsWith('image/'))return null;return await new Promise(ok=>{let fr=new FileReader();fr.onload=()=>ok(fr.result);fr.readAsDataURL(b)})}
async function addReportPages(j,d){let p=d.payload||{};j.addPage();let y=18,txt=(s,x,yy,size=10,b=false)=>{j.setFont('helvetica',b?'bold':'normal');j.setFontSize(size);j.setTextColor(23,32,51);j.text(String(s||''),x,yy)};txt('Bautagesbericht',18,y,20,true);txt(d.document_number||'',192,y,9,true);y+=12;[['Datum',p.date?new Date(p.date+'T12:00:00').toLocaleDateString('de-DE'):'' ],['Kunde',p.customer_name],['Baustelle / Projekt',p.site],['Wetter',p.weather],['Temperatur',p.temperature!==''&&p.temperature!=null?p.temperature+' °C':''],['Mitarbeiter vor Ort',p.workers],['Arbeitsstunden gesamt',p.hours]].forEach(a=>{if(!a[1])return;txt(a[0]+':',18,y,9,true);txt(a[1],68,y,9);y+=6});for(const [h,v] of [['Ausgeführte Arbeiten',p.work],['Material / Lieferungen',p.material],['Behinderungen / Besonderheiten',p.issues],['Notizen',p.note]]){if(!v)continue;y+=4;txt(h,18,y,10,true);y+=5;j.setFont('helvetica','normal');j.setFontSize(9);let lines=j.splitTextToSize(String(v),174);if(y+lines.length*4.5>275){j.addPage();y=18}j.text(lines,18,y);y+=lines.length*4.5}let imgs=(p.attachments||[]).filter(a=>String(a?.type||'').startsWith('image/')||/\.(png|jpe?g|webp)$/i.test(a?.path||a||''));for(let a of imgs){let path=typeof a==='string'?a:a.path,data=await imageData(path).catch(()=>null);if(!data)continue;j.addPage();txt('Anlage zum Bautagesbericht '+(d.document_number||''),18,16,10,true);try{let prop=j.getImageProperties(data),maxW=174,maxH=250,r=Math.min(maxW/prop.width,maxH/prop.height),w=prop.width*r,h=prop.height*r;j.addImage(data,prop.fileType||'JPEG',18,24,w,h)}catch{}}}
window.hpShareInvoiceBundle=async id=>{let inv=docs().find(x=>String(x.id)===String(id));if(!inv)return;let ids=[...document.querySelectorAll('.hpBundleReport:checked')].map(x=>x.value),rr=reportsFor(inv).filter(x=>ids.includes(String(x.id))),s=$('hpBundleStatus');if(!rr.length)return s.textContent='Bitte mindestens einen Bautagesbericht auswählen.';try{s.textContent='PDF wird erstellt …';let blob=await window.hpBuildInvoicePdf(inv),buf=await blob.arrayBuffer();await loadJsPdf();let j=window.jspdf.jsPDF.load?await window.jspdf.jsPDF.load(buf):null;if(!j){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/+esm'),src=await pdfjs.PDFDocument.load(buf),out=await pdfjs.PDFDocument.create(),pages=await out.copyPages(src,src.getPageIndices());pages.forEach(p=>out.addPage(p));for(let r of rr){let tmp=new window.jspdf.jsPDF({unit:'mm',format:'a4'});tmp.deletePage(1);await addReportPages(tmp,r);let rb=tmp.output('arraybuffer'),rd=await pdfjs.PDFDocument.load(rb),rp=await out.copyPages(rd,rd.getPageIndices());rp.forEach(p=>out.addPage(p))}let bytes=await out.save(),file=new File([bytes],`${inv.document_number||'Rechnung'}-mit-Bautagesberichten.pdf`,{type:'application/pdf'});if(navigator.share&&navigator.canShare?.({files:[file]})){closeModal?.();return navigator.share({title:`Rechnung ${inv.document_number||''}`,text:'Anbei erhalten Sie die Rechnung mit den zugehörigen Bautagesberichten.',files:[file]})}let a=document.createElement('a');a.href=URL.createObjectURL(file);a.download=file.name;a.click();s.textContent='✓ PDF erstellt';return} }catch(e){if(e.name!=='AbortError'){console.error(e);if(s)s.textContent='PDF konnte nicht erstellt werden: '+e.message}}};
function decorate(){document.querySelectorAll('#docList .item,#docList .card').forEach(card=>{let m=(card.textContent||'').match(/Rechnung\s+(RE-[0-9-]+)/i);if(!m)return;let num=m[1],actions=card.querySelector('.actions')||card,bs=[...card.querySelectorAll('button')].filter(b=>/Bautagesberichte/i.test(b.textContent||'')),b=bs[0];bs.slice(1).forEach(x=>x.remove());if(!b){b=document.createElement('button');b.className='btn secondary';b.textContent='📎 Bautagesberichte';let send=[...actions.querySelectorAll('button')].find(x=>/PDF senden/i.test(x.textContent||''));send?send.before(b):actions.appendChild(b)}b.onclick=e=>{e.preventDefault();e.stopPropagation();let inv=invoiceByNumber(num);if(inv)hpOpenBundle(inv.id)}})}
setTimeout(decorate,300);setInterval(decorate,1800);new MutationObserver(()=>setTimeout(decorate,0)).observe(document.documentElement,{subtree:true,childList:true});
})();